import { expect, test, uniqueName } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test("a file of exactly 10 MiB is accepted", { tag: "@DOC-05" }, async ({ apiAs }) => {
    const member = await apiAs("member");

    const vendorRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Doc Vendor"),
        category: "software",
        contact_email: "ops@doc-vendor.example.com",
      },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = await vendorRes.json();
    expect(vendor.status).toBe("draft");

    const tenMiB = 10 * 1024 * 1024;
    const buffer = Buffer.alloc(tenMiB, "a");

    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "contract",
        file: { name: "contract.txt", mimeType: "text/plain", buffer },
      },
    });
    expect(res.status(), await res.text()).toBe(201);
    const doc = await res.json();
    expect(doc.size_bytes, await res.text()).toBe(tenMiB);
    expect(doc.kind).toBe("contract");
  });
});
